if (typeof window._original_pluginSetService === 'undefined') {
    window._original_pluginSetService = window.pluginSetService;
    window.pluginSetService = function(name, status, version, suffix) {
        if (typeof window._original_pluginSetService === 'function') {
            window._original_pluginSetService(name, status, version, suffix);
        }
        if (name === 'op_waf') {
            renderWafAdditionalContent();
        }
    };
}

